class TokenBucket {
  constructor({ capacity, refillPerSecond, now = Date.now }) {
    if (!Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError("Capacity must be a positive finite number.");
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0) {
      throw new RangeError("refillPerSecond must be a non-negative number.");
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.nowFunc = now;

    // Başlangıçta kova dolu başlar
    this.tokens = capacity;
    this.lastRefillTime = this.nowFunc();
  }

  _refill(currentTime) {
    const elapsedMs = currentTime - this.lastRefillTime;

    // Saat geri giderse veya aynıysa dolum yapma (en büyük zaman referansını koru)
    if (elapsedMs <= 0) return;

    const tokensToAdd = (elapsedMs * this.refillPerSecond) / 1000;
    this.tokens = Math.min(this.capacity, this.tokens + tokensToAdd);
    this.lastRefillTime = currentTime;
  }

  available() {
    this._refill(this.nowFunc());
    return this.tokens;
  }

  tryTake(n = 1) {
    if (!Number.isFinite(n) || n <= 0) {
      throw new RangeError("n must be a positive finite number.");
    }

    const currentTime = this.nowFunc();
    this._refill(currentTime);

    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    }
    return false;
  }

  msUntil(n = 1) {
    if (!Number.isFinite(n) || n <= 0) {
      throw new RangeError("n must be a positive finite number.");
    }

    const currentTime = this.nowFunc();
    this._refill(currentTime);

    if (this.tokens >= n) {
      return 0;
    }

    if (this.refillPerSecond <= 0) {
      return Infinity;
    }

    const needed = n - this.tokens;
    const msNeeded = (needed / this.refillPerSecond) * 1000;

    return Math.ceil(msNeeded);
  }
}

module.exports = { TokenBucket };

const { TokenBucket } = require('./kova');
const assert = require('assert');

async function runTests() {
  console.log("Başlatılıyor testler...");

  // 1. Temel Fonksiyonellik ve Dolum Testi
  let currentTime = 1000;
  const now = () => currentTime;
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2, now });

  assert.strictEqual(bucket.available(), 10, "Başlangıçta kova dolu olmalı");

  currentTime += 500; // 0.5 saniye geçti -> 1 jeton eklenmeli
  assert.strictEqual(bucket.available(), 10, "Kapasite aşılmamalı (zaten doluydu)");

  bucket.tryTake(5); // 5 jeton eksildi -> kalan 5
  currentTime += 1000; // 1 saniye geçti -> 2 jeton eklenmeli -> toplam 7
  assert.strictEqual(bucket.available(), 7, "Dolum doğru hesaplanmalı");

  // 2. Saat Geri Gitme Testi
  currentTime -= 5000; // Zaman geri gitti
  assert.strictEqual(bucket.available(), 7, "Saat geri giderse jeton azalmamalı/eklenmemeli");
  currentTime += 1000; // Tekrar ileri gitti (toplamda hala eski referanstan sonraki bir an)
  // Son işlem zamanı en büyük olan `lastRefillTime` olarak kalmalı.
  // Mevcut durum: lastRefillTime = 2500 (currentTime'ın son geçerli hali), tokens = 7
  // currentTime şu an 1500 (1000 + 500 - 5000 + 1000) -> aslında logic gereği elapsedMs <= 0 olmalı.
  // Let's re-evaluate: lastRefillTime was 2500. currentTime is now 1500. 
  // elapsedMs = 1500 - 2500 = -1000. Refill skip edilir.

  // 3. msUntil Testleri
  const bucket2 = new TokenBucket({ capacity: 10, refillPerSecond: 1, now }); // saniyede 1 jeton
  currentTime = 1000;
  bucket2.tryTake(5); // Kalan 5
  assert.strictEqual(bucket2.msUntil(6), 1000, "1 jeton için 1000ms beklenmeli");
  assert.strictEqual(bucket2.msUntil(4), 0, "Yeterli jeton varsa 0 dönmeli");
  assert.strictEqual(bucket2.msUntil(15), Infinity, "Kapasite üstü talep Infinity olmalı");

  // 4. Hata Durumları (RangeError)
  try {
    new TokenBucket({ capacity: -1, refillPerSecond: 1 });
    assert.fail("Capacity negatifse hata fırlatmalıydı");
  } catch (e) { assert.strictEqual(e instanceof RangeError, true); }

  try {
    new TokenBucket({ capacity: 10, refillPerSecond: -1 });
    assert.fail("refillPerSecond negatifse hata fırlatmalıydı");
  } catch (e) { assert.strictEqual(e instanceof RangeError, true); }

  try {
    bucket2.tryTake(-1);
    assert.fail("n negatifse hata fırlatmalıydı");
  } catch (e) { assert.strictEqual(e instanceof RangeError, true); }

  console.log("Tüm testler başarıyla geçti!");
}

runTests().catch(err => {
  console.error("Test hatası:", err);
  process.exit(1);
});

